package com.bookeat.dining.service;
import com.bookeat.dining.dto.*;import com.bookeat.dining.enums.*;import com.bookeat.dining.entity.*;import com.bookeat.dining.repository.*;import com.bookeat.dining.mapper.*;
import com.bookeat.reservation.repository.*;import com.bookeat.reservation.entity.*;import com.bookeat.reservation.enums.*;import com.bookeat.reservation.service.InviteTokens;
import com.bookeat.restaurant.repository.*;import com.bookeat.restaurant.enums.ServiceType;import com.bookeat.restaurant.service.RestaurantAccessService;
import com.bookeat.table.repository.RestaurantTableRepository;import com.bookeat.table.enums.TableStatus;
import com.bookeat.order.repository.FoodOrderRepository;import com.bookeat.order.enums.FoodOrderStatus;
import com.bookeat.diniticket.service.*;import com.bookeat.diniticket.entity.DiniTicket;import com.bookeat.diniticket.repository.DiniTicketRepository;import com.bookeat.diniticket.dto.TicketRequests;import com.bookeat.diniticket.enums.TicketStatus;
import com.bookeat.availability.service.TableAllocationService;import com.bookeat.availability.repository.TableAllocationRepository;
import com.bookeat.commerce.service.*;import com.bookeat.common.audit.AuditService;import com.bookeat.common.response.PageResponse;import com.bookeat.exception.*;
import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import org.springframework.data.domain.*;import org.springframework.jdbc.core.JdbcTemplate;
import java.util.*;import java.time.*;import java.math.BigDecimal;
@Service @RequiredArgsConstructor @Transactional
public class DiningServiceImpl implements DiningService {
 private final DiningSessionRepository sessions;private final DiningMapper mapper;private final ReservationRepository reservations;private final ReservationStatusHistoryRepository history;private final RestaurantReservationSettingsRepository settings;private final RestaurantTableRepository tables;private final TableAllocationRepository allocations;private final TableAllocationService claims;private final CommerceAccess access;private final RestaurantAccessService owners;private final AuditService audit;private final Clock clock;private final JdbcTemplate jdbc;private final FoodOrderRepository orders;private final List<DiningPaymentPort> payments;private final DiniTicketService tickets;private final DiniTicketRepository ticketRepo;private final GroupBookingRepository groups;
 public DiningResponse gps(UUID actor,UUID id,DiningRequests.Gps q){var r=lockCustomer(actor,id);access.version(r.getVersion(),q.version());if(!Boolean.TRUE.equals(q.consent()))throw new ApiException(ErrorCode.LOCATION_CONSENT_REQUIRED);var cfg=settings.findByRestaurantId(r.getRestaurantId()).orElseThrow();var venue=access.lock(r.getRestaurantId());if(!cfg.isGpsCheckInEnabled()||venue.getLatitude()==null||venue.getLongitude()==null)throw new ApiException(ErrorCode.SERVICE_NOT_AVAILABLE);double distance=GeoRules.distanceKm(q.latitude().doubleValue(),q.longitude().doubleValue(),venue.getLatitude().doubleValue(),venue.getLongitude().doubleValue());if(!DiningRules.withinRadius(distance,cfg.getGpsCheckInRadiusMeters()))throw new ApiException(ErrorCode.CHECKIN_OUTSIDE_RADIUS);return check(actor,r,CheckInMethod.GPS,q.latitude(),q.longitude());}
 public DiningResponse qr(UUID actor,UUID id,DiningRequests.Qr q){var r=lockCustomer(actor,id);access.version(r.getVersion(),q.version());if(!settings.findByRestaurantId(r.getRestaurantId()).orElseThrow().isQrCheckInEnabled())throw new ApiException(ErrorCode.SERVICE_NOT_AVAILABLE);int n=jdbc.update("update dining_checkin_tokens set consumed_at=? where reservation_id=? and token_hash=? and consumed_at is null and expires_at>?",java.sql.Timestamp.from(clock.instant()),id,InviteTokens.hash(q.token()),java.sql.Timestamp.from(clock.instant()));if(n!=1)throw new ApiException(ErrorCode.CHECKIN_TOKEN_INVALID);return check(actor,r,CheckInMethod.QR,null,null);}
 public DiningResponse manual(UUID actor,UUID rid,UUID id,DiningRequests.Action q){access.lockOwner(actor,rid);var r=reservations.findById(id).filter(x->x.getRestaurantId().equals(rid)).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));access.version(r.getVersion(),q.version());return check(actor,r,CheckInMethod.OWNER_MANUAL,null,null);}
 public CheckinToken issue(UUID actor,UUID rid,UUID id){access.lockOwner(actor,rid);var r=reservations.findById(id).filter(x->x.getRestaurantId().equals(rid)).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));eligible(r);if(!settings.findByRestaurantId(rid).orElseThrow().isQrCheckInEnabled())throw new ApiException(ErrorCode.SERVICE_NOT_AVAILABLE);String token=InviteTokens.issue();Instant expiry=clock.instant().plusSeconds(300);if(expiry.isAfter(r.getEndsAt()))expiry=r.getEndsAt();jdbc.update("insert into dining_checkin_tokens(reservation_id,token_hash,expires_at) values(?,?,?) on conflict(reservation_id) do update set token_hash=excluded.token_hash,expires_at=excluded.expires_at,consumed_at=null",id,InviteTokens.hash(token),java.sql.Timestamp.from(expiry));return new CheckinToken(token,expiry);}
 private Reservation lockCustomer(UUID actor,UUID id){access.lock(reservations.restaurantId(id).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND)));return reservations.findByIdAndCustomerId(id,access.customer(actor)).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));}
 private void eligible(Reservation r){access.requireService(access.lock(r.getRestaurantId()),ServiceType.DINE_IN);if(r.getStatus()!=ReservationStatus.CONFIRMED)throw new ApiException(ErrorCode.BOOKING_STATE_INVALID);if(!DiningRules.arrivalWindow(clock.instant(),r.getStartsAt(),r.getEndsAt(),r.getNoShowAfter()))throw new ApiException(ErrorCode.CHECKIN_WINDOW_INVALID);}
 private DiningResponse check(UUID actor,Reservation r,CheckInMethod method,BigDecimal latitude,BigDecimal longitude){eligible(r);if(sessions.findByReservationId(r.getId()).isPresent())throw new ApiException(ErrorCode.DINING_STATE_INVALID);var allocation=allocations.findById(r.getAllocationId()).filter(a->a.isActive()&&!clock.instant().isBefore(a.getStartsAt())&&clock.instant().isBefore(a.getEndsAt())).orElseThrow(()->new ApiException(ErrorCode.TABLE_NOT_AVAILABLE));var t=tables.lockOwned(r.getTableId(),r.getRestaurantId()).orElseThrow();if(t.getStatus()!=TableStatus.AVAILABLE)throw new ApiException(ErrorCode.TABLE_NOT_AVAILABLE);t.setStatus(TableStatus.OCCUPIED);var venue=access.lock(r.getRestaurantId());venue.setChangeSequence(venue.getChangeSequence()+1);
  var d=new DiningSession();d.setReservationId(r.getId());d.setCustomerId(r.getCustomerId());d.setRestaurantId(r.getRestaurantId());d.setTableId(r.getTableId());d.setStatus(DiningStatus.CHECKED_IN);d.setCheckInMethod(method);d.setCheckInLatitude(latitude);d.setCheckInLongitude(longitude);d.setCheckedInAt(clock.instant());d.setBillTotal(BigDecimal.ZERO);sessions.saveAndFlush(d);reservationStatus(r,actor,ReservationStatus.CHECKED_IN,"Arrival verified");r.setCheckedInAt(clock.instant());audit.record(actor,"DINING_CHECKED_IN","DiningSession",d.getId(),null);sessions.flush();return mapper.view(d);}
 @Transactional(readOnly=true) public List<DiningResponse> current(UUID actor){return sessions.findByCustomerIdAndStatusNotIn(access.customer(actor),Set.of(DiningStatus.CHECKED_OUT,DiningStatus.CANCELLED)).stream().map(mapper::view).toList();}
 @Transactional(readOnly=true) public DiningResponse get(UUID actor,UUID id){return mapper.view(sessions.findById(id).filter(d->d.getCustomerId().equals(access.customer(actor))).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND)));}
 @Transactional(readOnly=true) public PageResponse<DiningResponse> ownerList(UUID actor,UUID rid,int page,int size){owners.getOwnedRestaurant(actor,rid);return PageResponse.from(sessions.findByRestaurantId(rid,PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"createdAt","id"))).map(mapper::view));}
 public DiningResponse action(UUID actor,UUID rid,UUID id,DiningRequests.Action q,String action){access.lockOwner(actor,rid);var d=sessions.findById(id).filter(x->x.getRestaurantId().equals(rid)).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));access.version(d.getVersion(),q.version());switch(action){
 case "start"->{if(d.getStatus()!=DiningStatus.CHECKED_IN)throw new ApiException(ErrorCode.DINING_STATE_INVALID);d.setStatus(DiningStatus.DINING);d.setDiningStartedAt(clock.instant());if(d.getReservationId()!=null)reservationStatus(reservations.findById(d.getReservationId()).orElseThrow(),actor,ReservationStatus.DINING,q.reason());}
 case "request-payment"->{if(!DiningRules.canOrder(d.getStatus()))throw new ApiException(ErrorCode.DINING_STATE_INVALID);var food=food(d);if(food.stream().anyMatch(o->!Set.of(FoodOrderStatus.SERVED,FoodOrderStatus.COMPLETED,FoodOrderStatus.CANCELLED,FoodOrderStatus.REJECTED).contains(o.getStatus())))throw new ApiException(ErrorCode.ORDER_IN_PROGRESS);d.setBillTotal(food.stream().filter(o->o.getStatus()!=FoodOrderStatus.CANCELLED&&o.getStatus()!=FoodOrderStatus.REJECTED).map(o->o.getTotal()).reduce(BigDecimal.ZERO,BigDecimal::add));d.setPaymentPendingAt(clock.instant());d.setStatus(DiningStatus.PAYMENT_PENDING);if(settled(d)){d.setStatus(DiningStatus.PAID);d.setPaidAt(clock.instant());}}
 case "checkout"->{if(d.getStatus()!=DiningStatus.PAID&&d.getStatus()!=DiningStatus.PAYMENT_PENDING)throw new ApiException(ErrorCode.DINING_STATE_INVALID);if(!settled(d))throw new ApiException(ErrorCode.PAYMENT_REQUIRED);if(food(d).stream().anyMatch(o->o.getStatus()!=FoodOrderStatus.COMPLETED&&o.getStatus()!=FoodOrderStatus.CANCELLED&&o.getStatus()!=FoodOrderStatus.REJECTED))throw new ApiException(ErrorCode.ORDER_IN_PROGRESS);d.setStatus(DiningStatus.CHECKED_OUT);d.setPaidAt(d.getPaidAt()==null?clock.instant():d.getPaidAt());d.setCheckedOutAt(clock.instant());d.setCheckInLatitude(null);d.setCheckInLongitude(null);if(d.getReservationId()!=null){var r=reservations.findById(d.getReservationId()).orElseThrow();claims.release(actor,rid,r.getAllocationId(),r.getId());var t=tables.lockOwned(r.getTableId(),rid).orElseThrow();if(t.getStatus()==TableStatus.OCCUPIED){t.setStatus(TableStatus.AVAILABLE);var venue=access.lock(rid);venue.setChangeSequence(venue.getChangeSequence()+1);}r.setCompletedAt(clock.instant());reservationStatus(r,actor,ReservationStatus.COMPLETED,q.reason());groups.findByReservationId(r.getId()).ifPresent(g->g.setStatus(GroupStatus.COMPLETED));}else{var t=ticketRepo.findById(d.getDiniTicketId()).orElseThrow();tickets.action(actor,rid,t.getId(),new TicketRequests.Action(t.getVersion(),q.reason()),TicketStatus.COMPLETED);}}
 default->throw new ApiException(ErrorCode.VALIDATION_FAILED);}
 sessions.flush();audit.record(actor,"DINING_"+action.toUpperCase(Locale.ROOT),"DiningSession",id,null);return mapper.view(d);}
 private List<com.bookeat.order.entity.FoodOrder> food(DiningSession d){return d.getReservationId()!=null?orders.findByReservationId(d.getReservationId()):orders.findByDiniTicketId(d.getDiniTicketId());}
 private boolean settled(DiningSession d){if(food(d).stream().noneMatch(o->o.getStatus()!=FoodOrderStatus.CANCELLED&&o.getStatus()!=FoodOrderStatus.REJECTED&&o.getTotal().signum()>0))return true;return !payments.isEmpty()&&payments.stream().allMatch(p->p.settled(d.getReservationId(),d.getDiniTicketId()));}
 private void reservationStatus(Reservation r,UUID actor,ReservationStatus target,String reason){var h=new ReservationStatusHistory();h.setReservationId(r.getId());h.setOldStatus(r.getStatus());h.setNewStatus(target);h.setChangedBy(actor);h.setChangedAt(clock.instant());h.setReason(reason);history.save(h);r.setStatus(target);reservations.flush();}
}
